    const scripted = scriptedProvider([
      [{type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}}, STOP_FOR_TOOL],
      [{type: 'text', text: 'recovered'}, STOP_DONE],
    ]);
    const seenMessages: string[] = [];
    const provider: AIProvider = {
      ...scripted,
      sendMessage(params: SendMessageParams) {
        seenMessages.push(JSON.stringify(params.messages));
        return scripted.sendMessage(params);
      },
    };
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

    const reply = await orchestrator.processMessage(createSession('ask'));

    expect({reply, seenQ: seenMessages[1]?.includes('q'), executorCalls: executor.mock.calls.length}).toEqual({
      reply: 'recovered',
      seenQ: true,
      executorCalls: 0,
    });
  });

  it('stops after one round when nothing asked for a tool', async () => {
    const provider = scriptedProvider([[{type: 'text', text: 'done'}, STOP_DONE], [{type: 'text', text: 'never'}]]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'x'}));
